const conceptFile = path.join(bundle, 'example.md');
const concept = body => `---\ntype: Concept\ntitle: Identity proof\n---\n\n${body}\n`;
fs.writeFileSync(indexFile, index);
fs.writeFileSync(conceptFile, concept('ORIGINAL'));
const initial = f.run('initial-index-import', ['wiki', 'okf', 'import', bundle, '--json']);
assert.equal(initial.code, 0, initial.stderr);
const first = JSON.parse(initial.stdout);
const page = path.join(vault, first.pagePaths[0]);
const original = fs.readFileSync(page);
const namesBefore = fs.readdirSync(path.join(vault, 'concepts')).sort();
const malformed = Buffer.concat([Buffer.from(index), Buffer.from([0xff])]);
fs.writeFileSync(indexFile, malformed);
fs.writeFileSync(conceptFile, concept('UPDATED after repair'));
const corrupt = f.run('corrupted-index-import', ['wiki', 'okf', 'import', bundle, '--json']);
if (f.phase === 'red') {
  assert.equal(corrupt.code, 0, corrupt.stderr);
  assert.equal(JSON.parse(corrupt.stdout).updatedCount, 1);
  assert.equal(fs.readFileSync(page).equals(original), false);
} else {
  assert.equal(corrupt.code, 1);
  assert.match(corrupt.stderr, /index\.md.*UTF-8/);
  assert.equal(fs.readFileSync(page).equals(original), true);
  assert.deepEqual(fs.readdirSync(path.join(vault, 'concepts')).sort(), namesBefore);
}
assert.ok(fs.readFileSync(indexFile).equals(malformed));
const preserved = fs.readFileSync(page).equals(original);
fs.writeFileSync(indexFile, index);
const recovery = f.run('repaired-index-import', ['wiki', 'okf', 'import', bundle, '--json']);
assert.equal(recovery.code, 0, recovery.stderr);
assert.deepEqual(JSON.parse(recovery.stdout).pagePaths, first.pagePaths);
assert.ok(fs.readFileSync(page, 'utf8').includes('UPDATED after repair'));
assert.deepEqual(fs.readdirSync(path.join(vault, 'concepts')).sort(), namesBefore);
f.receipt.observations.push({corruptExit: corrupt.code, originalPagePreserved: preserved, conceptCountBefore: namesBefore.length, conceptCountAfter: namesBefore.length, inputBytesUnchanged: true, recoveryExit: recovery.code, samePageIdentity: true});
f.finish();
