| `italic` | boolean | `true` |
| `underline` | boolean | `true` |
| `strikethrough` | boolean | `true` |
| `superscript` | boolean | `true` |
| `subscript` | boolean | `true` |
| `fontSize` | number or string | `14` or `"14pt"` |
| `fontFamily` | string | `"Arial"` |
| `fontWeight` | string or number | `"bold"`, `300`, `700` |
